Given a square chessboard of size n × n, the initial position knightPos[] and target position targetPos[] of a Knight are given. Find the minimum number of moves required for the Knight to reach targetPos.A Knight moves in an L-shape, covering 2 cells in one direction and 1 cell perpendicular to it. From (x, y), it can move to:(x ± 2, y ± 1)(x ± 1, y ± 2)This gives at most 8 possible moves: Note: The positions are given using 1-based indexing.Examples: Input: n = 3, knightPos[] = [3, 3], targetPos[]= [1, 2]Output: 1Explanation: Knight takes 1 step to reach from  (3, 3) to (1 ,2).Input: n = 6, knightPos[] = [1, 3], targetPos[] = [5, 1]Output: 2Explanation: In above diagram Knight takes 2 step to reach from (1, 3) to (5, 1): (1, 3) -> (3, 2) -> (5, 1)   Try It YourselfTable of Content[Naive Approach] Recursion and Backtracking - Exponential Time and O(n^2) Auxiliary Space[Expected Approch] BFS - Shortest Path in O(n^2) Time and O(n^2) Space[Naive Approach] Recursion and Backtracking - Exponential Time and O(n^2) Auxiliary SpaceThe idea is to explore all possible paths that the Knight can take from the initial position to the target and find the path requiring the minimum number of steps.From each position, the Knight can make at most 8 moves. We recursively explore every valid move until the target is reached.A visited array is used to avoid revisiting a cell in the current path. After exploring a move, we unmark the cell to allow it in other paths.
            C++

    #include <bits/stdc++.h>
using namespace std;

int solve(int x, int y, int tx, int ty, int n,
          vector<vector<bool>>& visited) {

    // If target is reached
    if (x == tx && y == ty)
        return 0;

    int ans = INT_MAX;

    // All 8 possible Knight moves
    int dx[] = {2, 2, -2, -2, 1, 1, -1, -1};
    int dy[] = {1, -1, 1, -1, 2, -2, 2, -2};

    for (int i = 0; i < 8; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        // Check if the new position is valid and unvisited
        if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
            !visited[nx][ny]) {

            visited[nx][ny] = true;

            int steps = solve(nx, ny, tx, ty, n, visited);

            if (steps != INT_MAX)
                ans = min(ans, 1 + steps);

            // Backtrack
            visited[nx][ny] = false;
        }
    }

    return ans;
}

int minStepToReachTarget(vector<int>& knightPos,
                         vector<int>& targetPos, int n) {

    // Convert 1-based indexing to 0-based indexing
    int x = knightPos[0] - 1;
    int y = knightPos[1] - 1;
    int tx = targetPos[0] - 1;
    int ty = targetPos[1] - 1;

    vector<vector<bool>> visited(n, vector<bool>(n, false));

    visited[x][y] = true;

    return solve(x, y, tx, ty, n, visited);
}

int main() {
    int n = 3;

    vector<int> knightPos = {3, 3};
    vector<int> targetPos = {1, 2};

    cout << minStepToReachTarget(knightPos, targetPos, n);

    return 0;
}


